fn reselect<'a>(f:&Fixture,ctl:&'a ControlRoot,h:&Held<'_>,hold:&roots::Exclusive<'_>,jh:&roots::Exclusive<'_>,current:HostConfirmation,policy:&[u8],i:&mut Inputs)->ControlAdmission<'a>{
 i.c01_store_original=c01_store(&i.store).unwrap();i.store.c01_selection_binding=selected("originals","c01-store.json",&i.c01_store_original);let root=i.store_binding.root_id.clone();i.store_binding=selected(&root,"store.json",&canonical(&i.store).unwrap());
 let runtime=RuntimeCommitSelection{execution_scope:hold.root().selection().execution_scope.clone(),store_binding:i.store_binding.clone(),c01_store_binding:i.store.c01_selection_binding.clone(),generation_manifest_binding:selected("originals","current-manifest.json",&canonical(&i.manifest).unwrap()),commit_authority_binding:i.commit_authority_binding.clone(),expires_utc_ns:i.authority_expires_utc_ns,operation_id:i.manifest.operation_id.clone(),original_fingerprint:i.manifest.original_fingerprint.clone()};
 ControlAdmission::fixture(ctl,File::open(f.base.join("control")).unwrap(),h,hold,jh,current,policy,&i.store.control_root_binding,runtime).unwrap()
}
