#[test]fn locally_expired_admission_fences_new_cold_and_outcome_but_settles_persisted_outcome(){for point in 0..4{
 fixture!(f,h,l,hold,jh,s,i,n,a,adm,ctl,current,policy);drop(adm);let deadline=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos() as u64+2_000_000_000;i.authority_expires_utc_ns=deadline;let adm=reselect(&f,&ctl,&h,&hold,&jh,current.clone(),&policy,&mut i);let mut c=Commit::begin_fixture(&hold,&jh,&h,&l,adm,s,i).unwrap();publish(&f,&mut c,&a,&n);c.prepare_pointer().unwrap();c.activate_pointer().unwrap();let mut observation=if point>0{let q=c.cold_request().unwrap();Some(ColdObservation::fixture(&q,result(&q),b"one original event\n".to_vec()).unwrap())}else{None};if point>=2{c.accept_cold(observation.take().unwrap()).unwrap();}if point==3{c.persist_outcome(&mut l).unwrap();}
 let at=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos() as u64;assert!(at<deadline,"fixture must reach selected boundary before expiry");std::thread::sleep(Duration::from_nanos(deadline-at+1_000_000));
 match point{0=>assert_eq!(c.cold_request().unwrap_err().0,"COMMIT_AUTHORITY_EXPIRED"),1=>assert_eq!(c.accept_cold(observation.unwrap()).unwrap_err().0,"COMMIT_AUTHORITY_EXPIRED"),2=>assert_eq!(c.persist_outcome(&mut l).unwrap_err().0,"COMMIT_AUTHORITY_EXPIRED"),_=>{let conf=c.requested_confirmation().unwrap().clone();c.acknowledge_outcome(&mut l,conf).unwrap();assert_eq!(c.confirmed_selection().unwrap().sequence,1);}}
 if point<3{assert!(l.outcome("operation-1").is_none());drop(c);recover_envelope_failure(&f,&ctl,&h,&hold,&jh,&mut l,current,true);}assert_eq!(l.inspect().known_events,1);
}}

