#[test]fn same_held_control_mutation_and_corruption_fence_new_cold_boundaries(){for at_acceptance in [false,true]{for mutation in 0..3{
 fixture!(f,h,l,hold,jh,s,i,n,a,adm,ctl,current,policy);let mut c=Commit::begin_fixture(&hold,&jh,&h,&l,adm,s,i).unwrap();publish(&f,&mut c,&a,&n);c.prepare_pointer().unwrap();c.activate_pointer().unwrap();let q=c.cold_request().unwrap();let observation=ColdObservation::fixture(&q,result(&q),b"one original event\n".to_vec()).unwrap();let original=restart_selection(&f);let root_bytes=fs::read(f.base.join("root/HEAD.json")).unwrap();let head=l.inspect().verified_head.clone();
 match mutation{0=>{append(&mut l,&h,Change::SlotState{slot_id:"source".into(),epoch:1,holder:"fixture-principal".into(),state:SlotPhase::Closing,terminal_binding:cb()});},1=>{let fingerprint=l.operation("operation-1").unwrap().fingerprint.clone();append(&mut l,&h,Change::Outcome{operation_id:"operation-1".into(),fingerprint,result_binding:cb(),outcome:Outcome::Quarantined});},_=>{let path=f.base.join("control/records/0000000000000001.json");let mut bytes=fs::read(&path).unwrap();bytes.push(b' ');fs::write(path,bytes).unwrap();}}
 if mutation<2{assert_ne!(l.inspect().verified_head,head);}let error=if at_acceptance{c.accept_cold(observation).unwrap_err()}else{c.cold_request().unwrap_err()};assert_eq!(error.0,"CONTROL_REFUSED");assert_eq!(restart_selection(&f),original);assert_eq!(fs::read(f.base.join("root/HEAD.json")).unwrap(),root_bytes);assert!(!f.base.join("control/commit-journal/commit-operation-1/cold-request.json").exists());assert_eq!(c.visibility(),Visibility::NewUnconfirmed);assert_eq!(l.inspect().known_events,1);
}}}
